# We build 10 core questions with 10 variations per subject = 100 questions per subject.

def get_clean_subject_id(subject_name):
    clean = subject_name.lower().replace("á", "a").replace("í", "i").replace("ê", "e").replace("ç", "c").replace("ã", "a").replace("é", "e")
    return clean

