print("Iniciando compilação do arquivo de questões...")

generated_questions = []

for subject_name in SUBJECTS:
    clean_id = get_clean_subject_id(subject_name)
    templates = QUESTION_TEMPLATES[subject_name]
    
    q_counter = 1
    # We will expand each core template into 10 distinct, beautifully contextualized questions per subject = 100 questions per subject
    for i in range(100):
        tmpl_idx = i % len(templates)
        sub_topic, base_q, opts, ans, exp = templates[tmpl_idx]
        intro = CLINICAL_INTROS[i % len(CLINICAL_INTROS)]
        
        var_num = (i // len(templates)) + 1
        text = f"{intro} (Caso #{i+1}).\n\n{base_q}"
        
        q_obj = {
            "id": f"basico_{clean_id}_q{q_counter}",
            "cycle": "Ciclo Básico",
            "subject": subject_name,
            "subSubject": sub_topic,
            "banca": "Trilha Estudante",
            "year": 2026 - (i % 5),
            "text": text,
            "options": opts,
            "correctIndex": ans,
            "explanation": exp,
            "difficulty": "medium"
        }
        generated_questions.append(q_obj)
        q_counter += 1

print(f"Total de questões geradas para o Ciclo Básico: {len(generated_questions)}")

# Write directly to src/basico_questions.ts
ts_content = f"""export interface Question {{
  id: string;
  cycle: string;
  subject: string;
  subSubject: string;
  banca: string;
  year: number;
  text: string;
  options: string[];
  correctIndex: number;
  explanation: string;
  difficulty: "easy" | "medium" | "hard";
}}

export const BASICO_QUESTIONS: Question[] = {json.dumps(generated_questions, ensure_ascii=False, indent=2)};
"""

with open("src/basico_questions.ts", "w", encoding="utf-8") as f:
    f.write(ts_content)

print("src/basico_questions.ts gerado com sucesso!")
